BEGIN;
CREATE SCHEMA delivery_test;CREATE FUNCTION delivery_test.assert(ok boolean,msg text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'ASSERT: %',msg;END IF;END $$;CREATE FUNCTION delivery_test.denied(statement text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE statement;EXCEPTION WHEN OTHERS THEN RETURN;END;RAISE EXCEPTION 'Expected rejection: %',statement;END $$;GRANT USAGE ON SCHEMA delivery_test TO anon,authenticated;GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA delivery_test TO anon,authenticated;
INSERT INTO auth.users(id,email) VALUES('2b000000-0000-4000-8000-000000000001','delivery@example.invalid');INSERT INTO public.companies(id,nome,created_by) VALUES('1b000000-0000-4000-8000-000000000001','Delivery fixture','2b000000-0000-4000-8000-000000000001'),('1b000000-0000-4000-8000-000000000002','Other fixture','2b000000-0000-4000-8000-000000000001');
INSERT INTO public.company_members(company_id,user_id,role,maintenance_role,created_by) VALUES('1b000000-0000-4000-8000-000000000001','2b000000-0000-4000-8000-000000000001','administrador','admin_empresa','2b000000-0000-4000-8000-000000000001');
INSERT INTO public.veiculos(id,company_id,placa,tipo,marca_modelo,km_atual,ano_fabricacao,ano_modelo,chassi,renavam) VALUES('3b000000-0000-4000-8000-000000000001','1b000000-0000-4000-8000-000000000001','EXL0001','caminhao','Volvo FH',1000,2022,2023,'9BWZZZ377VT004251','12345678901');
SELECT set_config('request.jwt.claim.sub','2b000000-0000-4000-8000-000000000001',true);
INSERT INTO public.maintenance_partners(id,company_id,razao_social,whatsapp,onboarding_profile) VALUES('4b000000-0000-4000-8000-000000000001','1b000000-0000-4000-8000-000000000001','Delivery workshop','11987654321','{"prazo_entrega_dias":3,"tipos_oficina":["Oficina mecânica"]}');

INSERT INTO public.maintenance_partners(id,company_id,razao_social,whatsapp,status) VALUES('4b000000-0000-4000-8000-000000000002','1b000000-0000-4000-8000-000000000001','Second workshop','21987654321','ativo'),('4b000000-0000-4000-8000-000000000003','1b000000-0000-4000-8000-000000000001','No contact',NULL,'ativo'),('4b000000-0000-4000-8000-000000000004','1b000000-0000-4000-8000-000000000001','Inactive workshop','31987654321','inativo'),('4b000000-0000-4000-8000-000000000005','1b000000-0000-4000-8000-000000000002','Other company','41987654321','ativo');

UPDATE public.maintenance_partners SET onboarding_profile='{"tipos_oficina":["Lavagem"]}' WHERE id='4b000000-0000-4000-8000-000000000002';
UPDATE public.maintenance_partners SET tipo='pecas_acessorios',onboarding_profile='{"tipos_oficina":["Peças e acessórios"]}' WHERE id='4b000000-0000-4000-8000-000000000003';
INSERT INTO public.veiculos(id,company_id,placa,tipo,marca_modelo,km_atual) VALUES('3b000000-0000-4000-8000-000000000002','1b000000-0000-4000-8000-000000000001','EXL0002','caminhao','Scania R',1000);
INSERT INTO public.maintenance_partners(id,company_id,razao_social,tipo,status) VALUES('4b000000-0000-4000-8000-000000000006','1b000000-0000-4000-8000-000000000001','Legacy without marked types','oficina_mecanica','ativo');
UPDATE public.maintenance_partners SET onboarding_profile='{"tipos_oficina":["Oficina mecânica"]}' WHERE id='4b000000-0000-4000-8000-000000000005';
SET LOCAL ROLE authenticated;
SELECT set_config('delivery_test.filtered',public.maintenance_order_command('1b000000-0000-4000-8000-000000000001','create','{"vehicle_id":"3b000000-0000-4000-8000-000000000002","partner_id":"4b000000-0000-4000-8000-000000000001","tipo":"corretiva","prioridade":"media","descricao_problema":"Repair needed","km_abertura":1000,"quote_partner_types":["oficina_mecanica"]}')->>'id',true);
SELECT delivery_test.assert((SELECT count(*)=1 FROM public.maintenance_order_dispatches WHERE order_id=current_setting('delivery_test.filtered')::uuid),'create payload applies type filter');

SELECT set_config('delivery_test.id',public.maintenance_order_command('1b000000-0000-4000-8000-000000000001','create','{"vehicle_id":"3b000000-0000-4000-8000-000000000001","partner_id":"4b000000-0000-4000-8000-000000000001","tipo":"corretiva","prioridade":"media","descricao_problema":"Repair needed","km_abertura":1000}')->>'id',true);
SELECT delivery_test.assert((SELECT count(*)=0 FROM public.maintenance_order_dispatches WHERE order_id=current_setting('delivery_test.id')::uuid),'empty filter never queues');
SELECT public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','select_quote_types',jsonb_build_object('id',current_setting('delivery_test.id'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'types',jsonb_build_array('oficina_mecanica')));
SELECT delivery_test.assert((SELECT count(*)=1 FROM public.maintenance_order_dispatches WHERE order_id=current_setting('delivery_test.id')::uuid AND status='pending'),'only explicit matching workshop queued');
SELECT delivery_test.assert((SELECT quote_partner_types=ARRAY['oficina_mecanica'] FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'filter persists');
SELECT delivery_test.assert(NOT maintenance_private.quote_partner_matches('1b000000-0000-4000-8000-000000000001','4b000000-0000-4000-8000-000000000004',ARRAY['oficina_mecanica']),'inactive never matches');
SELECT delivery_test.assert(NOT maintenance_private.quote_partner_matches('1b000000-0000-4000-8000-000000000001','4b000000-0000-4000-8000-000000000005',ARRAY['oficina_mecanica']),'other company never matches');
SELECT public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','select_quote_types',jsonb_build_object('id',current_setting('delivery_test.id'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'types',jsonb_build_array('lavagem','pecas_acessorios')));
SELECT delivery_test.assert((SELECT count(*)=2 FROM public.maintenance_order_dispatches WHERE order_id=current_setting('delivery_test.id')::uuid AND status='pending'),'multiple selected types use OR');
SELECT delivery_test.assert((SELECT count(*)=1 FROM public.maintenance_order_dispatches WHERE order_id=current_setting('delivery_test.id')::uuid AND status='obsolete'),'old excluded pending is obsolete');
SELECT delivery_test.denied($q$SELECT public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','select_quote_types',jsonb_build_object('id',current_setting('delivery_test.id'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'types',jsonb_build_array('fake_type')))$q$);
SELECT public.maintenance_partner_delete('1b000000-0000-4000-8000-000000000001','4b000000-0000-4000-8000-000000000002',(SELECT version FROM public.maintenance_partners WHERE id='4b000000-0000-4000-8000-000000000002'));
SELECT delivery_test.assert((SELECT deleted_at IS NOT NULL AND status='inativo' FROM public.maintenance_partners WHERE id='4b000000-0000-4000-8000-000000000002'),'delete persists tombstone');
SELECT delivery_test.assert((SELECT count(*)=1 FROM public.maintenance_partner_audit WHERE partner_id='4b000000-0000-4000-8000-000000000002' AND acao='exclusao'),'delete audited');
SELECT delivery_test.assert(NOT maintenance_private.quote_partner_matches('1b000000-0000-4000-8000-000000000001','4b000000-0000-4000-8000-000000000002',ARRAY['lavagem']),'deleted never matches');
SELECT delivery_test.denied($q$UPDATE public.maintenance_partners SET deleted_at=NULL,status='ativo' WHERE id='4b000000-0000-4000-8000-000000000002'$q$);
SELECT delivery_test.assert(public.maintenance_partner_delete('1b000000-0000-4000-8000-000000000001','4b000000-0000-4000-8000-000000000002',0)->>'deleted'='true','delete idempotent');
SELECT delivery_test.denied($q$SELECT public.maintenance_partner_delete('1b000000-0000-4000-8000-000000000002','4b000000-0000-4000-8000-000000000003',1)$q$);
SELECT delivery_test.denied($q$SELECT public.maintenance_partner_delete('1b000000-0000-4000-8000-000000000001','4b000000-0000-4000-8000-000000000003',0)$q$);
SELECT public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','select_quote_types',jsonb_build_object('id',current_setting('delivery_test.id'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'types','[]'::jsonb));
SELECT delivery_test.assert((SELECT count(*)=0 FROM public.maintenance_order_dispatches WHERE order_id=current_setting('delivery_test.id')::uuid AND status='pending'),'cleared filter obsoletes all pending');
SELECT delivery_test.assert(public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','claim',jsonb_build_object('id',current_setting('delivery_test.id'),'kind','abertura','dispatch_id',(SELECT id FROM public.maintenance_order_dispatches WHERE order_id=current_setting('delivery_test.id')::uuid LIMIT 1)))->>'status'='obsolete','direct stale claim blocked');
SELECT public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','select_quote_types',jsonb_build_object('id',current_setting('delivery_test.id'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'types',jsonb_build_array('oficina_mecanica')));
RESET ROLE;
UPDATE public.maintenance_order_dispatches SET status='unknown' WHERE order_id=current_setting('delivery_test.id')::uuid AND recipient_partner_id='4b000000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SELECT public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','select_quote_types',jsonb_build_object('id',current_setting('delivery_test.id'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'types','[]'::jsonb));
SELECT delivery_test.assert(public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','claim',jsonb_build_object('id',current_setting('delivery_test.id'),'kind','abertura','dispatch_id',(SELECT id FROM public.maintenance_order_dispatches WHERE order_id=current_setting('delivery_test.id')::uuid AND recipient_partner_id='4b000000-0000-4000-8000-000000000001')))->>'status'='unknown','filter cannot erase uncertain delivery');
SELECT public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','select_quote_types',jsonb_build_object('id',current_setting('delivery_test.id'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'types',jsonb_build_array('oficina_mecanica')));
SELECT delivery_test.assert((SELECT status='unknown' FROM public.maintenance_order_dispatches WHERE order_id=current_setting('delivery_test.id')::uuid AND recipient_partner_id='4b000000-0000-4000-8000-000000000001'),'reselecting never automatically repeats uncertain delivery');
RESET ROLE;
UPDATE public.company_members SET maintenance_role='supervisor',full_module_access=false WHERE company_id='1b000000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SELECT delivery_test.denied($q$SELECT public.maintenance_partner_delete('1b000000-0000-4000-8000-000000000001','4b000000-0000-4000-8000-000000000003',(SELECT version FROM public.maintenance_partners WHERE id='4b000000-0000-4000-8000-000000000003'))$q$);
ROLLBACK;
